"""Second question types for Process Design, Economics and Safety (PD)."""
from opl_dsl import Q

FILE, FRAMEWORK = "pd-second-types", "process-design"
ADD = [
    ("PD-1.1.A", Q("pd-nominal-from-effective", "design.economics", "What nominal annual rate, compounded {{per}} ({{m}} times a year), gives an effective annual rate of {{e}}%?",
        cases=[{"per": "monthly", "m": 12}, {"per": "quarterly", "m": 4}, {"per": "daily", "m": 365}], given={"e": {"pick": [5, 8, 12]}},
        value="m*((1 + e/100)^(1/m) - 1)*100", tex="r", verify="m*((1 + Rational(e, 100))**Rational(1, m) - 1)*100",
        explain="Invert $(1 + r/m)^m - 1$; the nominal rate is always a little below the effective one")),
    ("PD-1.1.B", Q("pd-capital-recovery", "design.economics", "A {{P}} thousand dollar plant must earn back its cost at {{i}}% over {{n}} years. What equal annual net cash flow, in thousand dollars, makes NPV zero (no salvage)?",
        given={"P": {"pick": [500, 1200, 3000]}, "i": {"pick": [8, 10, 15]}, "n": {"pick": [5, 10, 15]}}, value="P*(i/100)/(1 - (1 + i/100)^(-n))", tex="A",
        verify="solve(Eq(summation(x/(1 + Rational(i, 100))**Symbol('k'), (Symbol('k'), 1, n)), P), x)[0]",
        explain="The capital-recovery factor (A/P, i, n) turns a present cost into an equivalent annual charge")),
    ("PD-1.1.C", Q("pd-roi", "design.economics", "A {{P}} thousand dollar project returns {{cf}} thousand dollars a year in cash for {{n}} years and is depreciated straight-line to zero. What is its average return on investment, in % per year (profit after depreciation over investment)?",
        given={"P": {"pick": [400, 1000]}, "cf": {"pick": [150, 250, 400]}, "n": {"pick": [5, 8, 10]}}, require=["cf > P/n"], value="(cf - P/n)/P*100", tex="ROI",
        verify="(cf - Rational(P, n))/P*100", explain="ROI ignores the time value of money; it ranks projects quickly but NPV decides between them")),
    ("PD-1.2.A", Q("pd-capacity-from-budget", "design.economics", "A {{S1}} m³ vessel cost {{C1}} thousand dollars when the cost index was {{I1}}. With the index now {{I2}} and the six-tenths rule, what capacity, in m³, can {{C2}} thousand dollars buy?",
        given={"S1": {"pick": [10, 20]}, "C1": {"pick": [50, 80]}, "I1": {"pick": [500, 600]}, "I2": {"pick": [800, 820]}, "C2": {"pick": [120, 200]}},
        value="S1*(C2/C1*I1/I2)^(1/0.6)", tex="S_2", verify="solve(Eq(C1*(x/S1)**Rational(3, 5)*Rational(I2, I1), C2), x)[0]",
        explain="Invert the power law: doubling the budget at constant index buys about 3.2 times the capacity")),
    ("PD-1.2.B", Q("pd-soyd", "design.economics", "Equipment costs {{P}} thousand dollars with salvage {{Sv}} thousand and a {{n}}-year life. Under sum-of-years-digits depreciation, what is its book value after year {{k}}, in thousand dollars?",
        given={"P": {"pick": [100, 250]}, "Sv": {"pick": [0, 10, 25]}, "n": {"pick": [5, 8]}, "k": {"pick": [1, 2, 3]}},
        value="P - (P - Sv)*(k*n - k*(k - 1)/2)/(n*(n + 1)/2)", tex="BV",
        verify="P - summation((P - Sv)*(n - Symbol('j') + 1)/summation(Symbol('m'), (Symbol('m'), 1, n)), (Symbol('j'), 1, k))",
        explain="Year j takes (n − j + 1)/Σ of the depreciable amount: front-loaded like declining balance, but it lands exactly on the salvage value")),
    ("PD-2.1.A", Q("pd-flammable-check", "design.safety", "A fuel blend is {{a}}% methane (LFL 5.0%) and {{b}}% propane (LFL 2.1%) by volume. Air contains {{c}}% of this blend. Is the mixture below the lower flammable limit?",
        given={"a": {"pick": [50, 70, 90]}, "c": {"pick": [2.5, 3.5, 4.5]}}, let={"b": "100 - a"}, require=["abs(c - 1/(a/100/5 + (100 - a)/100/2.1)) > 0.1"],
        choice=["Below the LFL (too lean to burn)", "At or above the LFL (flammable)"], correct="c < 1/(a/100/5 + (100 - a)/100/2.1) ? 0 : 1",
        verify="0 if nsimplify(c) < 1/(Rational(a, 100)/5 + Rational(100 - a, 100)/Rational(21, 10)) else 1",
        explain="Le Chatelier's rule gives the blend's LFL; compare the concentration in air with it (and with the UFL, for the rich side)")),
    ("PD-2.1.B", Q("pd-tlv-allowance", "design.safety", "A workplace has {{c1}} ppm of a solvent (TLV {{t1}} ppm) and {{c2}} ppm of another (TLV {{t2}} ppm), with additive effects. How high, in ppm, may a third (TLV {{t3}} ppm) go before the mixture limit is exceeded?",
        given={"c1": {"pick": [20, 50]}, "t1": {"pick": [100, 200]}, "c2": {"pick": [5, 10]}, "t2": {"pick": [25, 50]}, "t3": {"pick": [50, 100, 500]}},
        require=["c1/t1 + c2/t2 < 0.9"], value="t3*(1 - c1/t1 - c2/t2)", tex="C_3", verify="solve(Eq(Rational(c1, t1) + Rational(c2, t2) + x/t3, 1), x)[0]",
        explain="The fractions of each limit add; whatever is left of 1 is the third component's share")),
    ("PD-2.1.C", Q("pd-hazop-word", "design.safety", "{{q}}", pace="recall",
        cases=[{"q": "Cooling water stops flowing to a reactor jacket. Which HAZOP guide word?", "o1": "NO (no flow)", "o2": "LESS", "o3": "REVERSE", "o4": "OTHER THAN"},
               {"q": "Product flows backwards through a pump into the feed tank. Which guide word?", "o1": "REVERSE", "o2": "NO", "o3": "MORE", "o4": "PART OF"},
               {"q": "A stream carries an unexpected contaminant alongside the intended material. Which guide word?", "o1": "AS WELL AS", "o2": "OTHER THAN", "o3": "PART OF", "o4": "MORE"},
               {"q": "Only one of two intended reagents reaches the reactor. Which guide word?", "o1": "PART OF", "o2": "AS WELL AS", "o3": "LESS", "o4": "NO"},
               {"q": "A completely different material is charged by mistake. Which guide word?", "o1": "OTHER THAN", "o2": "AS WELL AS", "o3": "PART OF", "o4": "REVERSE"},
               {"q": "Reactor temperature runs above its design value. Which guide word?", "o1": "MORE (more temperature)", "o2": "LESS", "o3": "OTHER THAN", "o4": "AS WELL AS"}],
        choice=["{{o1}}", "{{o2}}", "{{o3}}", "{{o4}}"], correct="0", verify="authored",
        explain="Guide word plus parameter makes the deviation (NO flow, MORE temperature); the team then asks for causes, consequences and safeguards")),
    ("PD-3.1.A", Q("pd-time-constant-from-data", "design.control", "After a step input, a first-order process has made {{p}}% of its final change at {{t}} min. What is its time constant, in minutes?",
        given={"p": {"pick": [40, 50, 75, 90]}, "t": {"pick": [2, 5, 12]}}, value="-t/log(1 - p/100)", tex="\\tau",
        verify="solve(Eq(log(1 - Rational(p, 100)), -t/x), x)[0]", explain="One reading fixes τ; plotting ln(1 − fraction) against t checks that the process really is first order")),
]
